// One query per automation, scoped by trigger_type, anti-joined against
// automation_runs so an entity that already SUCCEEDED for this
// automation is never reconsidered. A row with status = 'error' does
// NOT block — a transient failure (e.g. gmail hiccup) gets retried on
// the next poll. status = 'unsupported' DOES block, same as success —
// retrying an action with no executor (send_team_notification/send_sms)
// would just re-log 'unsupported' forever with no chance of succeeding.
// Automation metadata (trigger_config/condition_tree) travels along as
// a jsonb literal column rather than relying on cross-node pairedItem
// lookups, since automationId here is our own integer PK (not user
// input) it's safe to inline into the query text. `actions` is
// DELIBERATELY excluded from this literal — it holds the raw,
// not-yet-personalized email templates (e.g. "Hi {{first_name}}"), and
// this literal flows through Run Candidate Query's Query field, which
// is an n8n expression template (`={{ $json.sqlQuery }}`). n8n's
// expression engine treats ANY "{{ }}" it finds as ITS OWN syntax, so a
// merge token embedded in that string gets misread as an (invalid) n8n
// expression and silently renders as "undefined" — this is exactly the
// bug that caused live sends to say "Hi undefined". Evaluate & Expand
// Actions re-attaches the real `actions` (with intact merge tokens) by
// reading Select Active Automations' own output directly — plain data
// access in a Code node, never passed through an expression field.
// Task and Calendar both read from `activities` (see src/types/event.ts)
// — there is no separate calendar_events table in this schema.
const row = $input.item.json; // { id, trigger_type, trigger_config, condition_tree, actions }
const meta = JSON.stringify({
  automationId: row.id,
  entityType: row.trigger_type,
  triggerConfig: row.trigger_config,
  conditionTree: row.condition_tree,
});
const metaLiteral = `'${meta.replace(/'/g, "''")}'::jsonb`;
const id = row.id;

// owner_name resolves the {{owner_name}} merge token — contacts/companies
// use their own owner_id, opportunities use assigned_user, and
// tasks/calendar events (both `activities` rows) use the assigned user_id.
const queries = {
  contact: `SELECT c.id, c.first_name, c.last_name, c.email, c.lead_status, c.birthdate, c.city, c.state, c.country, ow.name AS owner_name,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'contact' AND tg.entity_id = c.id) AS tags,
      ${metaLiteral} AS automation_meta
    FROM contacts c
    LEFT JOIN users ow ON ow.id = c.owner_id
    WHERE c.is_archived = false
      AND NOT EXISTS (SELECT 1 FROM automation_runs r WHERE r.automation_id = ${id} AND r.entity_type = 'contact' AND r.entity_id = c.id AND r.status <> 'error');`,
  company: `SELECT co.id, co.name, NULL::text AS first_name, NULL::text AS last_name, NULL::text AS email, ow.name AS owner_name,
      co.account_status, co.city, co.state, co.country, co.annual_revenue, co.employee_count,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'company' AND tg.entity_id = co.id) AS tags,
      ${metaLiteral} AS automation_meta
    FROM companies co
    LEFT JOIN users ow ON ow.id = co.owner_id
    WHERE co.is_archived = false
      AND NOT EXISTS (SELECT 1 FROM automation_runs r WHERE r.automation_id = ${id} AND r.entity_type = 'company' AND r.entity_id = co.id AND r.status <> 'error');`,
  task: `SELECT act.id, act.subject AS name, ct.first_name, ct.last_name, ct.email, ow.name AS owner_name, act.is_completed, act.due_at,
      ${metaLiteral} AS automation_meta
    FROM activities act
    LEFT JOIN contacts ct ON ct.id = act.contact_id
    LEFT JOIN users ow ON ow.id = act.user_id
    WHERE act.due_at IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM automation_runs r WHERE r.automation_id = ${id} AND r.entity_type = 'task' AND r.entity_id = act.id AND r.status <> 'error');`,
  calendar: `SELECT act.id, act.subject AS name, ct.first_name, ct.last_name, ct.email, ow.name AS owner_name, act.type, act.due_at, act.is_completed,
      ${metaLiteral} AS automation_meta
    FROM activities act
    LEFT JOIN contacts ct ON ct.id = act.contact_id
    LEFT JOIN users ow ON ow.id = act.user_id
    WHERE act.due_at IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM automation_runs r WHERE r.automation_id = ${id} AND r.entity_type = 'calendar' AND r.entity_id = act.id AND r.status <> 'error');`,
  pipeline: `SELECT o.id, o.name, o.account_id, ct.first_name, ct.last_name, ct.email, ct.phone AS contact_phone, co.name AS company_name, ow.name AS owner_name, ow.email AS owner_email, ow.phone AS owner_phone, o.pipeline_id, o.stage_id, prop.public_token AS proposal_token,
      ${metaLiteral} AS automation_meta
    FROM opportunities o
    LEFT JOIN contacts ct ON ct.id = o.contact_id
    LEFT JOIN companies co ON co.id = o.account_id
    LEFT JOIN users ow ON ow.id = o.assigned_user
    LEFT JOIN LATERAL (
      SELECT p.public_token FROM proposals p WHERE p.opportunity_id = o.id ORDER BY p.created_at DESC LIMIT 1
    ) prop ON true
    WHERE o.is_archived = false
      AND NOT EXISTS (SELECT 1 FROM automation_runs r WHERE r.automation_id = ${id} AND r.entity_type = 'pipeline' AND r.entity_id = o.id AND r.status <> 'error');`,
};

const sqlQuery = queries[row.trigger_type];
if (!sqlQuery) return [];
return [{ json: { sqlQuery } }];

function getFieldValue(row, field) {
  if (field === 'age') {
    if (!row.birthdate) return null;
    const ms = Date.now() - new Date(row.birthdate).getTime();
    return Math.floor(ms / (365.25 * 24 * 3600 * 1000));
  }
  if (field === 'overdue') {
    return !row.is_completed && row.due_at && new Date(row.due_at) < new Date();
  }
  if (field === 'location') {
    return [row.city, row.state, row.country].filter(Boolean).join(', ');
  }
  return row[field];
}

function evalCondition(row, cond) {
  if (!cond || !cond.field) return true;
  const actual = getFieldValue(row, cond.field);
  const expected = cond.value;
  switch (cond.operator) {
    case 'equals': return Array.isArray(actual) ? actual.includes(expected) : String(actual) === String(expected);
    case 'not_equals': return Array.isArray(actual) ? !actual.includes(expected) : String(actual) !== String(expected);
    case 'contains': return String(actual || '').toLowerCase().includes(String(expected).toLowerCase());
    case 'greater_than': { const n = Number(actual); return Number.isFinite(n) ? n > Number(expected) : new Date(actual) > new Date(expected); }
    case 'less_than': { const n = Number(actual); return Number.isFinite(n) ? n < Number(expected) : new Date(actual) < new Date(expected); }
    case 'is_true': return Boolean(actual) === true;
    case 'is_false': return Boolean(actual) === false;
    default: return false;
  }
}

// Fans one input row out into zero or more action-items — a manual
// many-to-many reshape. Without an explicit `pairedItem` on each
// constructed item, n8n's automatic pairedItem inference for this kind
// of fan-out is unreliable once more than one row/action is in flight,
// which breaks every downstream $('Evaluate & Expand Actions').item
// lookup (Log Tag Result / Log Email Success / Log Unsupported) —
// they'd log the WRONG entity_id into automation_runs, so the real
// entity never gets deduped and re-fires on the next poll. Setting
// pairedItem explicitly here is what keeps that lineage correct.
// actions come from Select Active Automations' own output (plain data
// access, not a `={{ }}` expression field) rather than from the SQL
// literal, so raw merge tokens like {{first_name}} survive intact —
// see the comment on Build Candidate Query for why.
const actionsByAutomationId = {};
for (const it of $('Select Active Automations').all()) {
  actionsByAutomationId[it.json.id] = it.json.actions;
}

const output = [];
$input.all().forEach((item, itemIndex) => {
  const row = item.json;
  const meta = row.automation_meta;
  if (!meta) return;
  if (!evalCondition(row, meta.triggerConfig)) return;
  const branch = meta.conditionTree ? (evalCondition(row, meta.conditionTree) ? 'true' : 'false') : 'default';
  const actions = actionsByAutomationId[meta.automationId] || [];
  const actionsForBranch = actions.filter((a) => a.branch === branch);
  for (const action of actionsForBranch) {
    output.push({
      json: {
        automationId: meta.automationId,
        actionId: action.id,
        entityType: meta.entityType,
        entityId: row.id,
        branch,
        action,
        row,
      },
      pairedItem: { item: itemIndex },
    });
  }
});
return output;

// $env access can be blocked entirely by the n8n instance's own security settings (N8N_BLOCK_ENV_ACCESS_IN_NODE) — reading a blocked var THROWS rather than returning undefined, so a bare `$env.X || ''` never gets a chance to fall back.
function safeEnv(key) { try { return $env[key] || ''; } catch (e) { return ''; } }
const meta = $input.item.json;
const row = meta.row;
if (!row.email) {
  return [{ json: { automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch, status: 'error', detail: 'No email address available for this record.', hasEmail: false } }];
}

// Data arrives however a rep typed it (or a CSV import had it) —
// mirrors src/utils/text.ts's toTitleCase so merge fields don't send
// 'Hi pretty' for a name stored all-lowercase.
function toTitleCase(s) {
  return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' ');
}

// proposal_link only resolves for Pipeline triggers (row.proposal_token
// comes from a LATERAL join to that opportunity's most recent proposal
// in Build Candidate Query) — null for every other trigger_type.
const proposalLink = row.proposal_token ? `${safeEnv('FRONTEND_BASE_URL')}/documents/proposal/${row.proposal_token}` : '';

function fill(template) {
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, toTitleCase(row.first_name) || 'there')
    .replace(/{{\s*last_name\s*}}/gi, toTitleCase(row.last_name))
    .replace(/{{\s*deal_name\s*}}/gi, row.name || '')
    .replace(/{{\s*owner_name\s*}}/gi, toTitleCase(row.owner_name) || 'your account team')
    .replace(/{{\s*proposal_link\s*}}/gi, proposalLink)
    // Safety net: any OTHER "{{ ... }}" left over (a typo, a stray token
    // pasted in from an inserted Email Template's own content, etc.) must
    // be stripped here — Send Email's subject/message fields below are
    // n8n expression fields (`={{ $json.subject }}`), and n8n's own
    // expression engine will try to evaluate any "{{ }}" it finds in the
    // final string as ITS OWN syntax, silently rendering an unresolvable
    // one as the literal word "undefined" — the exact bug this app hit
    // before. Stripping here, before that field ever sees the text, is
    // what prevents a repeat for any token this function doesn't know.
    .replace(/{{[^{}]*}}/g, '');
}

return [{
  json: {
    automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch,
    hasEmail: true, to: row.email, subject: fill(meta.action.action_config.subject), body: fill(meta.action.action_config.body),
  },
}];

// Reached directly from two IF nodes (Is Add Tag? / Is Send Email?),
// neither of which touches the item's json — safe to read straight off
// $input.item rather than a cross-node pairedItem lookup.
const meta = $input.item.json;
return [{ json: { automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch, status: 'unsupported', detail: `No executor available for action_type "${meta.action.action_type}" on entity_type "${meta.entityType}".` } }];

// Contract Templates (Documents > Contracts) are standalone, deal-less
// content saved via ContractEditorPage — a rep references one directly in
// a Pipeline-triggered automation's Send Email action via the Documents
// picker, which inserts a {{contract_template:ID}} token (not a literal
// link, since the template has no deal/link of its own yet). Only
// Pipeline triggers have an opportunity to generate the contract against;
// for any other trigger_type the token is left for Prepare Email's
// existing "strip unknown {{ }}" fallback to clean up.
const meta = $input.item.json;
const subject = meta.action.action_config.subject || '';
const body = meta.action.action_config.body || '';
const match = meta.entityType === 'pipeline' ? (subject + ' ' + body).match(/\{\{\s*contract_template:(\d+)\s*\}\}/) : null;
return [{ json: { ...meta, contractTemplateId: match ? parseInt(match[1], 10) : null } }];

// $env access can be blocked entirely by the n8n instance's own security settings (N8N_BLOCK_ENV_ACCESS_IN_NODE) — reading a blocked var THROWS rather than returning undefined, so a bare `$env.X || ''` never gets a chance to fall back.
function safeEnv(key) { try { return $env[key] || ''; } catch (e) { return ''; } }
// Same merge-token handling as Prepare Email, plus resolving the
// {{contract_template:ID}} token (already validated present) into the
// real link for the contract just generated for this deal.
const meta = $('Detect Contract Template Token').item.json;
const row = meta.row;
const contract = $input.item.json;
const contractLink = `${safeEnv('FRONTEND_BASE_URL')}/documents/contract/${contract.public_token}`;

function toTitleCase(s) {
  return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' ');
}

const proposalLink = row.proposal_token ? `${safeEnv('FRONTEND_BASE_URL')}/documents/proposal/${row.proposal_token}` : '';

function fill(template) {
  return (template || '')
    .replace(/\{\{\s*contract_template:\d+\s*\}\}/gi, contractLink)
    .replace(/\{\{\s*first_name\s*\}\}/gi, toTitleCase(row.first_name) || 'there')
    .replace(/\{\{\s*last_name\s*\}\}/gi, toTitleCase(row.last_name))
    .replace(/\{\{\s*deal_name\s*\}\}/gi, row.name || '')
    .replace(/\{\{\s*owner_name\s*\}\}/gi, toTitleCase(row.owner_name) || 'your account team')
    .replace(/\{\{\s*proposal_link\s*\}\}/gi, proposalLink)
    .replace(/\{\{[^{}]*\}\}/g, '');
}

if (!row.email) {
  return [{ json: { automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch, status: 'error', detail: 'No email address available for this record.', hasEmail: false } }];
}

return [{
  json: {
    automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch,
    hasEmail: true, to: row.email, subject: fill(meta.action.action_config.subject), body: fill(meta.action.action_config.body),
  },
}];

// Proposal Templates (Documents > Proposals) are standalone, deal-less
// content saved via ProposalEditorPage — a rep references one directly in
// a Pipeline-triggered automation's Send Email action via the Documents
// picker, which inserts a {{proposal_template:ID}} token (not a literal
// link, since the template has no deal/link of its own yet). Only
// Pipeline triggers have an opportunity to generate the proposal against.
const meta = $input.item.json;
const subject = meta.action.action_config.subject || '';
const body = meta.action.action_config.body || '';
const match = meta.entityType === 'pipeline' ? (subject + ' ' + body).match(/\{\{\s*proposal_template:(\d+)\s*\}\}/) : null;
return [{ json: { ...meta, proposalTemplateId: match ? parseInt(match[1], 10) : null } }];

// $env access can be blocked entirely by the n8n instance's own security settings (N8N_BLOCK_ENV_ACCESS_IN_NODE) — reading a blocked var THROWS rather than returning undefined, so a bare `$env.X || ''` never gets a chance to fall back.
function safeEnv(key) { try { return $env[key] || ''; } catch (e) { return ''; } }
// Resolves {{proposal_template:ID}} into the real link for the proposal
// just generated for this deal, then hands off the SAME meta shape (with
// action.action_config.subject/body updated) so Detect Contract Template
// Token can keep scanning — a single email can reference both a proposal
// and a contract template.
const meta = $('Detect Proposal Template Token').item.json;
const proposal = $input.item.json;
const link = `${safeEnv('FRONTEND_BASE_URL')}/documents/proposal/${proposal.public_token}`;
const subject = (meta.action.action_config.subject || '').replace(/\{\{\s*proposal_template:\d+\s*\}\}/gi, link);
const body = (meta.action.action_config.body || '').replace(/\{\{\s*proposal_template:\d+\s*\}\}/gi, link);
return [{
  json: {
    ...meta,
    action: { ...meta.action, action_config: { ...meta.action.action_config, subject, body } },
  },
}];
